svg.script:
const baseUrl = 'https://pewcb.github.io/EEVblogForum/ProcessSteps/';
const frames = [
	'0001.png', '0002.png', '0003.png', '0004.jpg', '0005.jpg', '0006.jpg',
	'0007.jpg', '0008.jpg', '0009.jpg', '0010.jpg', '0015.jpg', '0017.jpg',
	'0018.jpg', '0020.jpg', '0021.jpg', '0022.jpg', '0023.jpg', '0024.jpg'
];
const delays = [
	1000, 1000, 1000, 1000, 1000, 1000,
	1000, 1000, 1000, 1000, 1000, 1000,
	1000, 1000, 1000, 1000, 1000, 1000
];
const slide = document.getElementById('slide');
let frameIndex = 0;

frames.forEach((file) => {
	const image = new Image();
	image.src = baseUrl + file;
});

function showFrame() {
	slide.setAttribute('href', baseUrl + frames[frameIndex]);
	setTimeout(() => {
		frameIndex = (frameIndex + 1) % frames.length;
		showFrame();
	}, delays[frameIndex]);
}

showFrame();
